internal class AppException: UniffiException {
    AppException() : base() {}
    AppException(String @Message) : base(@Message) {}

    // Each variant is a nested class


    public class Failure : AppException {
        // Members
        public string @message;

        // Constructor
        public Failure(
                string @message) : base(
                "@message" + "=" + @message) {

            this.@message = @message;
        }
    }



}

class FfiConverterTypeAppError : FfiConverterRustBuffer<AppException>, CallStatusErrorHandler<AppException> {
    public static FfiConverterTypeAppError INSTANCE = new FfiConverterTypeAppError();

    public override AppException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new AppException.Failure(
                    FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeAppError.Read()", value));
        }
    }

    public override int AllocationSize(AppException value) {
        switch (value) {

            case AppException.Failure variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeAppError.AllocationSize()", value));
        }
    }

    public override void Write(AppException value, BigEndianStream stream) {
        switch (value) {
            case AppException.Failure variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeAppError.Write()", value));
        }
    }
}





